<?php require 'includes/auth.php';require_role('buyer');require 'includes/order_service.php';$buyer=user()['id'];$items=buyer_cart_items($buyer);if(!$items){flash('error','Your cart is empty.');redirect('cart.php');}$a=db()->prepare('SELECT * FROM buyer_addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$a->execute([$buyer]);$addresses=$a->fetchAll();$subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$delivery=post('delivery_type');$address=(int)post('address_id');$payment=post('payment_method');if(!in_array($delivery,['delivery','pickup'],true)||!in_array($payment,['UPI_DEMO','COD'],true))$error='Choose delivery/pickup and a payment method.';elseif($delivery==='delivery'&&!$address)$error='Select or add a delivery address.';else{if($payment==='UPI_DEMO'){$_SESSION['pending_checkout']=['address_id'=>$address,'delivery_type'=>$delivery,'payment_method'=>'UPI_DEMO','token'=>bin2hex(random_bytes(24))];redirect('payment-demo.php');}try{$id=create_marketplace_order($buyer,$address,$delivery,'COD','pending');flash('success','Order placed with Cash on Delivery.');redirect('order-details.php?id='.$id);}catch(Throwable $e){$error=$e->getMessage();}}}$pageTitle='Checkout';require 'includes/header.php';?><div class="checkout"><section><p class="eyebrow">SECURE CHECKOUT</p><h1>Review & pay</h1><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><form method="post" class="card-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><h2>Fulfillment</h2><label class="radio"><input type="radio" name="delivery_type" value="delivery" checked> Delivery <small>₹50 flat fee</small></label><label class="radio"><input type="radio" name="delivery_type" value="pickup"> Seller pickup <small>Free</small></label><h2>Delivery address</h2><?php foreach($addresses as $ad):?><label class="address-choice"><input type="radio" name="address_id" value="<?=$ad['id']?>" <?=$ad['is_default']?'checked':''?>><span><b><?=e($ad['label'])?> — <?=e($ad['recipient_name'])?></b><br><?=e($ad['address_line'])?>, <?=e($ad['city'])?> · <?=e($ad['phone'])?></span></label><?php endforeach;?><?php if(!$addresses):?><p>No saved address. <a href="buyer/addresses.php">Add one before checkout</a>.</p><?php else:?><p><a href="buyer/addresses.php">Manage saved addresses</a></p><?php endif;?><h2>Payment method</h2><label class="address-choice"><input type="radio" name="payment_method" value="UPI_DEMO" checked><span><b>UPI Demo payment</b><br><small>Scan demo QR, then confirm payment. No real money is transferred.</small></span></label><label class="address-choice"><input type="radio" name="payment_method" value="COD"><span><b>Cash on Delivery</b><br><small>Payment stays pending until delivery.</small></span></label><button>Continue to payment</button></form></section><aside class="summary"><h2>Order summary</h2><?php foreach($items as $i):?><p><span><?=e($i['name'])?> × <?=$i['quantity']?> kg</span><strong>₹<?=number_format($i['price']*$i['quantity'],2)?></strong></p><?php endforeach;?><hr><p><span>Subtotal</span><strong>₹<?=number_format($subtotal,2)?></strong></p><p><span>Delivery</span><strong>₹50.00*</strong></p><p class="total"><span>Estimated total</span><strong>₹<?=number_format($subtotal+50,2)?></strong></p><small>*Free for pickup.</small></aside></div><?php require 'includes/footer.php'; ?>
